import{_ as a,o as l,c as s,ab as i}from"./chunks/framework.DCf1Sbhf.js";const u=JSON.parse('{"title":"agent","description":"","frontmatter":{},"headers":[],"relativePath":"ai/claudeCode/index.md","filePath":"ai/claudeCode/index.md","lastUpdated":1776412753000}'),n={name:"ai/claudeCode/index.md"};function o(t,e,p,r,d,c){return l(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="agent" tabindex="-1">agent <a class="header-anchor" href="#agent" aria-label="Permalink to &quot;agent&quot;">​</a></h1><p><strong>什么是Agent？</strong></p><p><code>&quot;One loop &amp; Bash is all you need&quot; ==&gt; 一个工具 + 一个循环 = 一个智能体。</code></p><p>Agent 产品 = 模型 + Harness</p><p>模型做决策。Harness 执行。模型做推理。Harness 提供上下文。模型是驾驶者。Harness 是载具。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Harness = Tools + Knowledge + Observation + Action Interfaces + Permissions</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    Tools:          文件读写、Shell、网络、数据库、浏览器</span></span>
<span class="line"><span>    Knowledge:      产品文档、领域资料、API 规范、风格指南</span></span>
<span class="line"><span>    Observation:    git diff、错误日志、浏览器状态、传感器数据</span></span>
<span class="line"><span>    Action:         CLI 命令、API 调用、UI 交互</span></span>
<span class="line"><span>    Permissions:    沙箱隔离、审批流程、信任边界</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Claude Code = 一个 agent loop</span></span>
<span class="line"><span>            + 工具 (bash, read, write, edit, glob, grep, browser...)</span></span>
<span class="line"><span>            + 按需 skill 加载</span></span>
<span class="line"><span>            + 上下文压缩</span></span>
<span class="line"><span>            + 子 agent 派生</span></span>
<span class="line"><span>            + 带依赖图的任务系统</span></span>
<span class="line"><span>            + 异步邮箱的团队协调</span></span>
<span class="line"><span>            + worktree 隔离的并行执行</span></span>
<span class="line"><span>            + 权限治理</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><h2 id="harness到底在做什么" tabindex="-1">Harness到底在做什么 <a class="header-anchor" href="#harness到底在做什么" aria-label="Permalink to &quot;Harness到底在做什么&quot;">​</a></h2><p>以下是真正的工作：</p><ul><li><p>实现工具。 给 agent 一双手。文件读写、Shell 执行、API 调用、浏览器控制、数据库查询。每个工具都是 agent 在环境中可以采取的一个行动。设计它们时要原子化、可组合、描述清晰。</p></li><li><p>策划知识。 给 agent 领域专长。产品文档、架构决策记录、风格指南、合规要求。按需加载（s05），不要前置塞入。Agent 应该知道有什么可用，然后自己拉取所需。</p></li><li><p>管理上下文。 给 agent 干净的记忆。子 agent 隔离（s04）防止噪声泄露。上下文压缩（s06）防止历史淹没。任务系统（s07）让目标持久化到单次对话之外。</p></li><li><p>控制权限。 给 agent 边界。沙箱化文件访问。对破坏性操作要求审批。在 agent 和外部系统之间实施信任边界。这是安全工程与 harness 工程的交汇点。</p></li><li><p>收集任务过程数据。 Agent 在你的 harness 中执行的每一条行动序列都是训练信号。真实部署中的感知-推理-行动轨迹是微调下一代 agent 模型的原材料。你的 harness 不仅服务于 agent -- 它还可以帮助进化 agent。</p></li></ul><hr><h1 id="glossary-术语表" tabindex="-1">Glossary (术语表) <a class="header-anchor" href="#glossary-术语表" aria-label="Permalink to &quot;Glossary (术语表)&quot;">​</a></h1><h2 id="agent-1" tabindex="-1">Agent <a class="header-anchor" href="#agent-1" aria-label="Permalink to &quot;Agent&quot;">​</a></h2><p>在这套仓库里，<code>agent</code> 指的是：<br><strong>一个能根据输入做判断，并且会调用工具去完成任务的模型。</strong></p><p>你可以简单理解成：</p><ul><li>模型负责思考</li><li>harness 负责给模型工作环境</li></ul><h2 id="harness" tabindex="-1">Harness <a class="header-anchor" href="#harness" aria-label="Permalink to &quot;Harness&quot;">​</a></h2><p><code>harness</code> 可以理解成“给 agent 准备好的工作台”。</p><p>它包括：</p><ul><li>工具</li><li>文件系统</li><li>权限</li><li>提示词</li><li>记忆</li><li>任务系统</li></ul><p>模型本身不是 harness。<br> harness 也不是模型。</p><h2 id="agent-loop" tabindex="-1">Agent Loop <a class="header-anchor" href="#agent-loop" aria-label="Permalink to &quot;Agent Loop&quot;">​</a></h2><p><code>agent loop</code> 是系统反复执行的一条主循环：</p><ol><li>把当前上下文发给模型</li><li>看模型是要直接回答，还是要调工具</li><li>如果调工具，就执行工具</li><li>把工具结果写回上下文</li><li>再继续下一轮</li></ol><p>没有这条循环，就没有 agent 系统。</p><h2 id="message-messages" tabindex="-1">Message / Messages <a class="header-anchor" href="#message-messages" aria-label="Permalink to &quot;Message / Messages&quot;">​</a></h2><p><code>message</code> 是一条消息。<br><code>messages</code> 是消息列表。</p><p>它通常包含：</p><ul><li>用户消息</li><li>assistant 消息</li><li>tool_result 消息</li></ul><p>这份列表就是 agent 最主要的工作记忆。</p><h2 id="tool" tabindex="-1">Tool <a class="header-anchor" href="#tool" aria-label="Permalink to &quot;Tool&quot;">​</a></h2><p><code>tool</code> 是模型可以调用的一种动作。</p><p>例如：</p><ul><li>读文件</li><li>写文件</li><li>改文件</li><li>跑 shell 命令</li><li>搜索文本</li></ul><p>模型并不直接执行系统命令。<br> 模型只是说“我要调哪个工具、传什么参数”，真正执行的是你的代码。</p><h2 id="tool-schema" tabindex="-1">Tool Schema <a class="header-anchor" href="#tool-schema" aria-label="Permalink to &quot;Tool Schema&quot;">​</a></h2><p><code>tool schema</code> 是工具的输入说明。</p><p>它告诉模型：</p><ul><li>这个工具叫什么</li><li>这个工具做什么</li><li>需要哪些参数</li><li>参数是什么类型</li></ul><p>可以把它想成“工具使用说明书”。</p><h2 id="dispatch-map" tabindex="-1">Dispatch Map <a class="header-anchor" href="#dispatch-map" aria-label="Permalink to &quot;Dispatch Map&quot;">​</a></h2><p><code>dispatch map</code> 是一张映射表：</p><div class="language-python vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;read_file&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: read_file_handler,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;write_file&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: write_file_handler,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;bash&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: bash_handler,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>意思是：</p><ul><li>模型说要调用 <code>read_file</code></li><li>代码就去表里找到 <code>read_file_handler</code></li><li>然后执行它</li></ul><h2 id="stop-reason" tabindex="-1">Stop Reason <a class="header-anchor" href="#stop-reason" aria-label="Permalink to &quot;Stop Reason&quot;">​</a></h2><p><code>stop_reason</code> 是模型这一轮为什么停下来的原因。</p><p>常见的有：</p><ul><li><code>end_turn</code>：模型说完了</li><li><code>tool_use</code>：模型要调用工具</li><li><code>max_tokens</code>：模型输出被截断了</li></ul><p>它决定主循环下一步怎么走。</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p><code>context</code> 是模型当前能看到的信息总和。</p><p>包括：</p><ul><li><code>messages</code></li><li>system prompt</li><li>动态补充信息</li><li>tool_result</li></ul><p>上下文不是永久记忆。<br> 上下文是“这一轮工作时当前摆在桌上的东西”。</p><h2 id="compact-compaction" tabindex="-1">Compact / Compaction <a class="header-anchor" href="#compact-compaction" aria-label="Permalink to &quot;Compact / Compaction&quot;">​</a></h2><p><code>compact</code> 指压缩上下文。</p><p>因为对话越长，模型能看到的历史就越多，成本和混乱也会一起增加。</p><p>压缩的目标不是“删除有用信息”，而是：</p><ul><li>保留真正关键的内容</li><li>去掉重复和噪声</li><li>给后面的轮次腾空间</li></ul><h2 id="subagent" tabindex="-1">Subagent <a class="header-anchor" href="#subagent" aria-label="Permalink to &quot;Subagent&quot;">​</a></h2><p><code>subagent</code> 是从当前 agent 派生出来的一个子任务执行者。</p><p>它最重要的价值是：</p><p><strong>把一个大任务放到独立上下文里处理，避免污染父上下文。</strong></p><h2 id="fork" tabindex="-1">Fork <a class="header-anchor" href="#fork" aria-label="Permalink to &quot;Fork&quot;">​</a></h2><p><code>fork</code> 在本仓库语境里，指一种子 agent 启动方式：</p><ul><li>不是从空白上下文开始</li><li>而是先继承父 agent 的已有上下文</li></ul><p>这适合“子任务必须理解当前讨论背景”的场景。</p><h2 id="permission" tabindex="-1">Permission <a class="header-anchor" href="#permission" aria-label="Permalink to &quot;Permission&quot;">​</a></h2><p><code>permission</code> 就是“这个工具调用能不能执行”。</p><p>一个好的权限系统通常要回答三件事：</p><ul><li>应不应该直接拒绝</li><li>能不能自动允许</li><li>剩下的是不是要问用户</li></ul><h2 id="permission-mode" tabindex="-1">Permission Mode <a class="header-anchor" href="#permission-mode" aria-label="Permalink to &quot;Permission Mode&quot;">​</a></h2><p><code>permission mode</code> 是权限系统的工作模式。</p><p>例如：</p><ul><li><code>default</code>：默认询问</li><li><code>plan</code>：只允许读，不允许写</li><li><code>auto</code>：简单安全的操作自动过，危险操作再问</li></ul><h2 id="hook" tabindex="-1">Hook <a class="header-anchor" href="#hook" aria-label="Permalink to &quot;Hook&quot;">​</a></h2><p><code>hook</code> 是一个插入点。</p><p>意思是：<br> 在不改主循环代码的前提下，在某个时机额外执行一段逻辑。</p><p>例如：</p><ul><li>工具调用前先检查一下</li><li>工具调用后追加一条审计信息</li></ul><h2 id="memory" tabindex="-1">Memory <a class="header-anchor" href="#memory" aria-label="Permalink to &quot;Memory&quot;">​</a></h2><p><code>memory</code> 是跨会话保存的信息。</p><p>但不是所有东西都该存 memory。</p><p>适合存 memory 的，通常是：</p><ul><li>用户长期偏好</li><li>多次出现的重要反馈</li><li>未来别的会话仍然有价值的信息</li></ul><h2 id="system-prompt" tabindex="-1">System Prompt <a class="header-anchor" href="#system-prompt" aria-label="Permalink to &quot;System Prompt&quot;">​</a></h2><p><code>system prompt</code> 是系统级说明。</p><p>它告诉模型：</p><ul><li>你是谁</li><li>你能做什么</li><li>你有哪些规则</li><li>你应该如何协作</li></ul><p>它比普通用户消息更稳定。</p><h2 id="system-reminder" tabindex="-1">System Reminder <a class="header-anchor" href="#system-reminder" aria-label="Permalink to &quot;System Reminder&quot;">​</a></h2><p><code>system reminder</code> 是每一轮临时追加的动态提醒。</p><p>例如：</p><ul><li>当前目录</li><li>当前日期</li><li>某个本轮才需要的额外上下文</li></ul><p>它和稳定的 system prompt 不是一回事。</p><h2 id="task" tabindex="-1">Task <a class="header-anchor" href="#task" aria-label="Permalink to &quot;Task&quot;">​</a></h2><p><code>task</code> 是持久化任务系统里的一个任务节点。</p><p>一个 task 通常不只是一句待办事项，还会带：</p><ul><li>状态</li><li>描述</li><li>依赖关系</li><li>owner</li></ul><h2 id="dependency-graph" tabindex="-1">Dependency Graph <a class="header-anchor" href="#dependency-graph" aria-label="Permalink to &quot;Dependency Graph&quot;">​</a></h2><p><code>dependency graph</code> 指任务之间的依赖关系图。</p><p>最简单的理解：</p><ul><li>A 做完，B 才能开始</li><li>C 和 D 可以并行</li><li>E 要等 C 和 D 都完成</li></ul><p>这类结构能帮助 agent 判断：</p><ul><li>现在能做什么</li><li>什么被卡住了</li><li>什么能同时做</li></ul><h2 id="worktree" tabindex="-1">Worktree <a class="header-anchor" href="#worktree" aria-label="Permalink to &quot;Worktree&quot;">​</a></h2><p><code>worktree</code> 是 Git 提供的一个机制：</p><p>同一个仓库，可以在多个不同目录里同时展开多个工作副本。</p><p>它的价值是：</p><ul><li>并行做多个任务</li><li>不互相污染文件改动</li><li>便于多 agent 并行工作</li></ul><h2 id="mcp" tabindex="-1">MCP <a class="header-anchor" href="#mcp" aria-label="Permalink to &quot;MCP&quot;">​</a></h2><p><code>MCP</code> 是 Model Context Protocol。</p><p>你可以先把它理解成一套统一接口，让 agent 能接入外部工具。</p><p>它解决的核心问题是：</p><ul><li>工具不必都写死在主程序里</li><li>可以通过统一协议接入外部能力</li></ul><h2 id="runtime-task" tabindex="-1">Runtime Task <a class="header-anchor" href="#runtime-task" aria-label="Permalink to &quot;Runtime Task&quot;">​</a></h2><p><code>runtime task</code> 指的是：</p><blockquote><p>系统当前正在运行、等待完成、或者刚刚结束的一条执行单元。</p></blockquote><p>例如：</p><ul><li>一个后台 <code>pytest</code></li><li>一个正在工作的 teammate</li><li>一个正在运行的 monitor</li></ul><p>它和 <code>task</code> 不一样。</p><ul><li><code>task</code> 更像工作目标</li><li><code>runtime task</code> 更像执行槽位</li></ul><h2 id="teammate" tabindex="-1">Teammate <a class="header-anchor" href="#teammate" aria-label="Permalink to &quot;Teammate&quot;">​</a></h2><p><code>teammate</code> 是长期存在的队友 agent。</p><p>它和 <code>subagent</code> 的区别是：</p><ul><li><code>subagent</code>：一次性委派，干完就结束</li><li><code>teammate</code>：长期存在，可以反复接任务</li></ul><p>如果你发现自己开始把这两个词混用，说明你需要回看：</p><ul><li><code>s04</code></li><li><code>s15</code></li><li><code>entity-map.md</code></li></ul><h2 id="protocol" tabindex="-1">Protocol <a class="header-anchor" href="#protocol" aria-label="Permalink to &quot;Protocol&quot;">​</a></h2><p><code>protocol</code> 就是一套提前约好的协作规则。</p><p>它回答的是：</p><ul><li>消息应该长什么样</li><li>收到以后要怎么处理</li><li>批准、拒绝、超时这些状态怎么记录</li></ul><p>在团队章节里，它最常见的形状是：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>request</span></span>
<span class="line"><span>  -&gt;</span></span>
<span class="line"><span>response</span></span>
<span class="line"><span>  -&gt;</span></span>
<span class="line"><span>status update</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h2 id="envelope" tabindex="-1">Envelope <a class="header-anchor" href="#envelope" aria-label="Permalink to &quot;Envelope&quot;">​</a></h2><p><code>envelope</code> 本意是“信封”。</p><p>在程序里，它表示：</p><blockquote><p>把正文和一些元信息一起包起来的一条结构化记录。</p></blockquote><p>例如一条协议消息里，正文之外还会附带：</p><ul><li><code>from</code></li><li><code>to</code></li><li><code>request_id</code></li><li><code>timestamp</code></li></ul><p>这整包东西，就可以叫一个 <code>envelope</code>。</p><h2 id="state-machine" tabindex="-1">State Machine <a class="header-anchor" href="#state-machine" aria-label="Permalink to &quot;State Machine&quot;">​</a></h2><p><code>state machine</code> 不是很玄的高级理论。</p><p>你可以先把它理解成：</p><blockquote><p>一张“状态可以怎么变化”的规则表。</p></blockquote><p>例如：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>pending -&gt; approved</span></span>
<span class="line"><span>pending -&gt; rejected</span></span>
<span class="line"><span>pending -&gt; expired</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>这就是一个最小状态机。</p><h2 id="router" tabindex="-1">Router <a class="header-anchor" href="#router" aria-label="Permalink to &quot;Router&quot;">​</a></h2><p><code>router</code> 可以简单理解成“分发器”。</p><p>它的任务是：</p><ul><li>看请求属于哪一类</li><li>把它送去正确的处理路径</li></ul><p>例如工具层里：</p><ul><li>本地工具走本地 handler</li><li><code>mcp__...</code> 工具走 MCP client</li></ul><h2 id="control-plane" tabindex="-1">Control Plane <a class="header-anchor" href="#control-plane" aria-label="Permalink to &quot;Control Plane&quot;">​</a></h2><p><code>control plane</code> 可以理解成“负责协调和控制的一层”。</p><p>它通常不直接产出最终业务结果，<br> 而是负责决定：</p><ul><li>谁来执行</li><li>在什么环境里执行</li><li>有没有权限</li><li>执行后要不要通知别的模块</li></ul><p>这个词第一次看到容易怕。<br> 但在本仓库里，你只需要把它先记成：</p><blockquote><p>不直接干活，负责协调怎么干活的一层。</p></blockquote><h2 id="capability" tabindex="-1">Capability <a class="header-anchor" href="#capability" aria-label="Permalink to &quot;Capability&quot;">​</a></h2><p><code>capability</code> 就是“能力项”。</p><p>例如在 MCP 里，能力不只可能是工具，还可能包括：</p><ul><li>tools</li><li>resources</li><li>prompts</li><li>elicitation</li></ul><p>所以 <code>capability</code> 比 <code>tool</code> 更宽。</p><h2 id="resource" tabindex="-1">Resource <a class="header-anchor" href="#resource" aria-label="Permalink to &quot;Resource&quot;">​</a></h2><p><code>resource</code> 可以理解成：</p><blockquote><p>一个可读取、可引用、但不一定是“执行动作”的外部内容入口。</p></blockquote><p>例如：</p><ul><li>一份文档</li><li>一个只读配置</li><li>一块可被模型读取的数据内容</li></ul><p>它和 <code>tool</code> 的区别是：</p><ul><li><code>tool</code> 更像动作</li><li><code>resource</code> 更像可读取内容</li></ul><h2 id="elicitation" tabindex="-1">Elicitation <a class="header-anchor" href="#elicitation" aria-label="Permalink to &quot;Elicitation&quot;">​</a></h2><p><code>elicitation</code> 可以先理解成：</p><blockquote><p>外部系统反过来向用户要补充输入。</p></blockquote><p>也就是说，不再只是 agent 主动调用外部能力。<br> 外部能力也可能说：</p><p>“我还缺一点信息，请你补一下。”</p><h2 id="最容易混的几对词" tabindex="-1">最容易混的几对词 <a class="header-anchor" href="#最容易混的几对词" aria-label="Permalink to &quot;最容易混的几对词&quot;">​</a></h2><table tabindex="0"><thead><tr><th>词对</th><th>最简单的区分方法</th></tr></thead><tbody><tr><td><code>message</code> vs <code>system prompt</code></td><td>一个更像对话内容，一个更像系统说明</td></tr><tr><td><code>todo</code> vs <code>task</code></td><td>一个更像临时步骤，一个更像持久化工作节点</td></tr><tr><td><code>task</code> vs <code>runtime task</code></td><td>一个管目标，一个管执行</td></tr><tr><td><code>subagent</code> vs <code>teammate</code></td><td>一个一次性，一个长期存在</td></tr><tr><td><code>tool</code> vs <code>resource</code></td><td>一个更像动作，一个更像内容</td></tr><tr><td><code>permission</code> vs <code>hook</code></td><td>一个决定能不能做，一个决定要不要额外插入行为</td></tr></tbody></table>`,180)])])}const m=a(n,[["render",o]]);export{u as __pageData,m as default};
